from contextlib import AsyncExitStack, aclosing, asynccontextmanager, nullcontext
import time

from django.http.response import StreamingHttpResponse


def _note_cleanup_failure(primary, cleanup):
    # Keep diagnostics bounded and omit exception text (paths/credentials).
    prefix = "Response cleanup failed: "
    notes = getattr(primary, "__notes__", ())
    if sum(note.startswith(prefix) for note in notes) < 8:
        primary.add_note(prefix + type(cleanup).__name__[:80])


@asynccontextmanager
async def _preserve_cleanup(context):
    resource = await context.__aenter__()
    try:
        yield resource
    except GeneratorExit as closing:
        # aclose() uses GeneratorExit as control flow. A close failure must
        # reach the owner, which knows the actual read/send/cancellation error.
        await context.__aexit__(type(closing), closing, closing.__traceback__)
        raise
    except BaseException as primary:
        try:
            await context.__aexit__(type(primary), primary, primary.__traceback__)
        except BaseException as cleanup:
            _note_cleanup_failure(primary, cleanup)
        raise
    else:
        await context.__aexit__(None, None, None)


class AsyncResponse(StreamingHttpResponse):
    """
    Provides the `is_async_fileresponse` attribute checked by
    fileresponse.handlers.AsyncFileASGIHandler.

    Contains the core content streaming logic which is the same
    for files and other file like streams.
    """

    is_async_fileresponse = True
    response_options = {"content_type", "status", "reason", "charset", "headers"}

    def __init__(self, *args, **kwargs):
        self.chunk_size = kwargs.get("chunk_size", 4096)
        if (
            isinstance(self.chunk_size, bool)
            or not isinstance(self.chunk_size, int)
            or not 1 <= self.chunk_size <= 1024 * 1024
        ):
            raise ValueError("chunk_size must be an integer between 1 and 1048576")
        self.raw_headers = kwargs.get("raw_headers", {})

        # copy relevant super kwargs from kwargs
        super_kwargs = {key: kwargs[key] for key in self.response_options if key in kwargs}

        # set default values
        header_options = kwargs.get("headers") or {}
        self._content_type_explicit = (
            kwargs.get("content_type") is not None
            or any(name.lower() == "content-type" for name in header_options)
        )
        if not self._content_type_explicit:
            super_kwargs["content_type"] = "application/octet-stream"
        self._expected_length = None
        self._source_complete = False
        self._stream_claimed = False
        self._stream_override = None
        self._source_iterator = self._source_content()
        self._content_iterators = []
        super().__init__(self._source_iterator, **super_kwargs)

    @StreamingHttpResponse.streaming_content.setter
    def streaming_content(self, value):
        # A replacement may change the representation size, as with Django GZip.
        self._body_transformed = value is not self._source_iterator
        if self._body_transformed:
            self.headers.pop("Content-Length", None)
        StreamingHttpResponse.streaming_content.__set__(self, value)
        if hasattr(value, "aclose") and not any(value is item for item in self._content_iterators):
            self._content_iterators.append(value)

    def _apply_source_metadata(self, length, content_type):
        if isinstance(length, int) and not isinstance(length, bool) and length >= 0:
            self._expected_length = length
            if not self._body_transformed and "Content-Length" not in self:
                self["Content-Length"] = str(length)
        if (
            not self._content_type_explicit
            and self.get("Content-Type") == "application/octet-stream"
            and isinstance(content_type, str)
            and content_type
            and all(32 <= ord(char) < 127 for char in content_type)
        ):
            self["Content-Type"] = content_type

    @property
    def response_headers(self):
        # copied from django.core.handlers.asgi.ASGIHandler.send_response
        response_headers = []
        for header, value in self.items():
            if isinstance(header, str):
                header = header.encode("ascii")
            if isinstance(value, str):
                value = value.encode("latin1")
            response_headers.append((bytes(header).lower(), bytes(value)))
        for c in self.cookies.values():
            response_headers.append(
                (b"set-cookie", c.output(header="").encode("ascii").strip())
            )
        return response_headers

    async def _read_chunks(self, stream):
        while chunk := await stream.read(self.chunk_size):
            yield chunk

    async def _stream_content(self):
        # Adapters override this async generator to own their resource contexts.
        if False:
            yield b""

    async def _source_content(self):
        # Resolve the source lazily: legacy adapters supply their open stream
        # only after middleware has captured this response's iterator.
        # Direct iteration through Django's StreamingHttpResponse interface
        # (stock ASGIHandler, test client) admits here, after its headers.
        direct = not self._stream_claimed
        self._stream_claimed = True
        admission = self._admit_source() if direct else nullcontext(self._stream_override)
        async with _preserve_cleanup(admission) as source:
            self._stream_override = source
            content = self._stream_content() if source is None else self._read_chunks(source)
            received = 0
            async with _preserve_cleanup(aclosing(content)):
                async for chunk in content:
                    received += len(chunk)
                    if self._expected_length is not None and received > self._expected_length:
                        raise OSError("Source length mismatch: extra bytes")
                    yield chunk
                if self._expected_length is not None and received != self._expected_length:
                    raise OSError("Source length mismatch: early EOF")
                self._source_complete = True

    @asynccontextmanager
    async def _admit_source(self):
        """Acquire a source before headers; custom adapters may override this."""
        yield None

    async def stream(self, send):
        """Send the content currently installed by async streaming middleware."""
        await self._stream_response(send)

    async def _stream_response(self, send, stream=None):
        # No await before the claim: concurrent callers cannot change the source.
        if self._stream_claimed:
            raise RuntimeError("Response stream already consumed")
        self._stream_claimed = True
        admission = self._admit_source() if stream is None else nullcontext(stream)
        async with _preserve_cleanup(admission) as source:
            self._stream_override = source
            await self._stream_admitted(send)

    async def __aiter__(self):
        # Django's __aiter__ does not close the iterator it wraps, so a direct
        # consumer stopping early (disconnect, break) would leave the source open.
        async with self._owned_content() as content:
            async for part in content:
                yield part

    @asynccontextmanager
    async def _owned_content(self):
        # Close installed middleware iterators as well as the original source;
        # async generators need not forward aclose() to the iterators they wrap.
        async with AsyncExitStack() as resources:
            for iterator in self._content_iterators:
                await resources.enter_async_context(_preserve_cleanup(aclosing(iterator)))
            yield await resources.enter_async_context(
                _preserve_cleanup(aclosing(StreamingHttpResponse.__aiter__(self)))
            )

    async def _stream_admitted(self, send):
        async with self._owned_content() as content:
            await self._send_content(content, send)

    async def send_stream_to_client(self, stream, send):
        """Bind an already-open stream and send middleware-wrapped content."""
        # Delegate internally without recursing into a legacy stream(send).
        await self._stream_response(send, stream)

    async def _send_content(self, content, send):
        started_serving = time.perf_counter()
        await send(
            {
                "type": "http.response.start",
                "status": self.status_code,
                "headers": self.response_headers,
            }
        )
        async for chunk in content:
            await send(
                {
                    "type": "http.response.body",
                    "body": chunk,
                    "more_body": True,
                }
            )
        if self._expected_length is not None and not self._source_complete:
            raise OSError("Source length mismatch: source not exhausted")
        await send({"type": "http.response.body", "body": b"", "more_body": False})
        self.elapsed = time.perf_counter() - started_serving

