from aiobotocore.session import get_session

from django.conf import settings
from django.core.exceptions import ImproperlyConfigured


class AiobotocoreFileResponse(AsyncResponse):
    """
    Async response class for serving files from an s3 compatible object store
    like [MinIO](http://min.io). Its admission context owns both the client
    and body, including when middleware wraps the content.

    It uses aiobotocore to get the stream object from which chunks of data could be
    read asynchronously.
    """

    def __init__(self, bucket, key, chunk_size=4096, **kwargs):
        response_kwargs = {key: value for key, value in kwargs.items() if key in self.response_options}
        super().__init__(chunk_size=chunk_size, **response_kwargs)
        self.client_config = self.create_client_config(kwargs)
        self.bucket = bucket
        self.key = key

    def __repr__(self):
        return "<%(cls)s status_code=%(status_code)d>" % {
            "cls": self.__class__.__name__,
            "status_code": self.status_code,
        }

    def create_client_config(self, kwargs):
        options = (
            ("endpoint_url", "endpoint_url", "FILERESPONSE_S3_ENDPOINT_URL"),
            ("region_name", "region_name", "FILERESPONSE_S3_REGION"),
            ("aws_access_key_id", "aws_access_key_id", "FILERESPONSE_S3_ACCESS_KEY_ID"),
            ("aws_secret_access_key", "secret_access_key", "FILERESPONSE_S3_SECRET_ACCESS_KEY"),
        )
        config = {}
        for client_option, override, setting_name in options:
            if override in kwargs:
                config[client_option] = kwargs[override]
            else:
                try:
                    config[client_option] = getattr(settings, setting_name)
                except AttributeError as exc:
                    raise ImproperlyConfigured(
                        f"Set {setting_name} or pass {override!r}"
                    ) from exc
        config["use_ssl"] = (
            kwargs["use_ssl"] if "use_ssl" in kwargs
            else getattr(settings, "FILERESPONSE_S3_USE_SSL", False)
        )
        return config

    @asynccontextmanager
    async def _admit_source(self):
        session = get_session()
        async with _preserve_cleanup(session.create_client("s3", **self.client_config)) as client:
            minio_response = await client.get_object(Bucket=self.bucket, Key=self.key)
            async with _preserve_cleanup(minio_response["Body"]) as stream:
                self._apply_source_metadata(
                    minio_response.get("ContentLength"), minio_response.get("ContentType")
                )
                yield stream